package com.newzkl.platform.base.biz.order.infrastructure.entity;import com.baomidou.mybatisplus.annotation.TableName;import com.newzkl.platform.base.common.ddd.model.entity.BaseDO;import lombok.Data;import lombok.EqualsAndHashCode;import org.dromara.autotable.annotation.Index;/** * 售后操作记录表 DO * * @author sijiwang * @since 2026-01-23 */@EqualsAndHashCode(callSuper = true)@Data@TableNamepublic class RefundOperationRecordDO extends BaseDO {    /**     * spu订单id     */    @Index    private Long spuOrderId;    /**     * 售后单refund表的主键     */    @Index    private Long refundId;    /**     * 操作人ID     */    private Long operatorId;    /**     * 操作方角色编码（对应RoleEnum.CompanyRole的code：1000=C端客户，1001=供应商，1002=渠道商，0=平台等）     */    private Long operatorRoleCode;    /**     * 操作方客户端类型（对应CommonEnum.Client的code：user=用户端，supplier=供应商端，channel=渠道商端，admin=平台端等）     */    private String operatorClient;    /**     * 操作方名称     */    private String operatorName;    /**     * 操作前售后单状态（对应RefundEnum.State的code）     */    private Integer beforeState;    /**     * 操作后售后单状态（对应RefundEnum.State的code）     */    private Integer afterState;    /**     * 操作类型（0=发起退款申请，1=审核通过，2=审核拒绝，3=提交物流信息，4=确认收货，5=退款完成，6=关闭售后，7=平台介入）     */    @Index    private Integer operationType;    /**     * 操作内容描述     */    private String operationContent;    /**     * 本次操作涉及的退款金额（单位：分，和refund表保持一致）     */    private Integer refundAmount;    /**     * 物流公司名称     */    private String freightCompanyName;    /**     * 物流单号     */    @Index    private String freightNo;    /**     * 操作原因/备注     */    private String reason;    /**     * 拓展字段（JSON格式存储额外信息）     */    private String ext;}